import { copyFile, cp, mkdir, readdir, readFile, writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

const root = fileURLToPath(new URL('../', import.meta.url));
const publicDir = path.join(root, 'public');
const docsDir = path.join(root, 'docs');

await mkdir(docsDir, { recursive: true });

const projectData = await readFile(path.join(root, 'src/data/projects.js'), 'utf8');
await writeFile(
  path.join(docsDir, 'project-data.js'),
  '// Generated by npm run sync:static. Edit src/data/projects.js instead.\n' + projectData,
);

const caseDirectories = ['article-pipeline', 'pm-harness', 'she-ji-qian-zhi'];
for (const directory of caseDirectories) {
  await cp(path.join(publicDir, directory), path.join(docsDir, directory), {
    recursive: true,
  });
}

const sharedFiles = [
  'case-theme.css',
  'case-theme.js',
  'hero-poster.jpg',
  // NOTE (2026-10-20): profile-image.webp and parth-resume.docx were removed
  // from public/ when the resume sections were deleted from the site.
];
const publicEntries = await readdir(publicDir, { withFileTypes: true });
sharedFiles.push(
  ...publicEntries
    .filter((entry) => entry.isFile() && /^project-.*\.svg$/.test(entry.name))
    .map((entry) => entry.name),
);

for (const filename of sharedFiles) {
  await copyFile(path.join(publicDir, filename), path.join(docsDir, filename));
}

console.log(`Synced project data, ${caseDirectories.length} case directories and ${sharedFiles.length} shared files to docs/.`);
